        // 正确版本继续推进不受影响
        fumigationService.approve(order.id(), new ApproveRequest("f-appr-ap4", "审批人乙", 2));
        assertEquals(FumigationStatus.APPROVED, fumigationService.getOrder(order.id()).order().status());
