    @Test
    void invalidStateTransitionsRejected() {
        SiloView silo = newSilo("S-STATE");
        FanView fan = newFan("F-STATE");
        FumigationView order = newOrder(silo.id(), "state");

        ApiException startEarly = assertThrows(ApiException.class,
